import numpy as np

class PolicyNet:
    def __init__(self, ns, na):
        self.W = np.random.randn(ns, na) * 0.01
    def policy(self, s):
        logits = self.W[s]
        exp = np.exp(logits - logits.max())
        return exp / exp.sum()
    def sample(self, s): return np.random.choice(len(self.W[s]), p=self.policy(s))

env_ns, env_na = 16, 4
pi = PolicyNet(env_ns, env_na)

for ep in range(500):
    traj = []
    s = 0
    for _ in range(100):
        a = pi.sample(s)
        s2 = (s + a) % env_ns  # simplified
        r = 10 if s2 == 15 else -0.1
        traj.append((s, a, r))
        s = s2
        if s == 15: break
    # Compute returns
    G = np.zeros(len(traj))
    G[-1] = traj[-1][2]
    for t in range(len(traj)-2, -1, -1):
        G[t] = traj[t][2] + 0.99 * G[t+1]
    # Update
    for t, (s, a, _) in enumerate(traj):
        pi.W[s] += 0.01 * G[t] * (np.eye(env_na)[a] - pi.policy(s))

print('Policy learned! Best actions per state:')

import numpy as np

class DQNAgent:
    def __init__(self, ns, na, lr=0.001, gamma=0.99, eps=0.1):
        self.Q = np.random.randn(ns, na) * 0.01
        self.gamma = gamma
        self.eps = eps
        self.lr = lr
    def act(self, s):
        if np.random.rand() < self.eps: return np.random.randint(self.Q.shape[1])
        return np.argmax(self.Q[s])
    def update(self, s, a, r, s2, done):
        target = r if done else r + self.gamma * self.Q[s2].max()
        self.Q[s,a] += self.lr * (target - self.Q[s,a])

agent = DQNAgent(16, 4)
for ep in range(1000):
    s, total_r = 0, 0
    for _ in range(100):
        a = agent.act(s)
        s2 = (s + a) % 16
        r = 10 if s2 == 15 else -0.1
        agent.update(s, a, r, s2, s2==15)
        s, total_r = s2, total_r + r
        if s == 15: break
print('DQN trained! Average reward:', total_r)

from fastapi import FastAPI
import pickle
import numpy as np

app = FastAPI()
with open('model.pkl', 'rb') as f:
    model = pickle.load(f)

@app.post('/predict')
def predict(features: list):
    prediction = model.predict(np.array(features).reshape(1, -1))
    return {'prediction': int(prediction[0])}

@app.get('/health')
def health():
    return {'status': 'healthy', 'model_type': type(model).__name__}')

